#include "ksPartModulationTask.h"
#include <iostream>
#include <stdexcept>
static void check(bool b){if(!b)throw std::runtime_error("Part modulation property failed");}
int main(){using T=ks::PartModulationTask;uint64_t cases=0;for(unsigned kind=0;kind<4;++kind)for(unsigned input=0;input<256;++input)for(unsigned gate=0;gate<256;++gate){T t{T::Kind(kind)};unsigned writes=0,controls=0,refreshes=0,globals=0,guard=0;auto part=uint8_t(input+gate);auto read=[&](T::Read r)->uint32_t{return r==T::Read::Input?input:gate;};auto write=[&](bool word,uint16_t v){check(t.part()==part&&word==(kind==0));unsigned expected=kind==0?(input==255?512:input*2):kind==3?uint8_t(uint16_t(input*input*2)>>8):input;check(v==expected);++writes;};auto store=[&](){return (input&1)?0u:3u;};while(t.stage()!=T::Stage::Complete){check(++guard<32);auto child=t.child();if(child!=T::Child::None){if(child==T::Child::Control)++controls;if(child==T::Child::Refresh)++refreshes;if(child==T::Child::Globals)++globals;check(t.resumeChild(part));continue;}auto c=t.nextClocks(store),s=unsigned(t.stage());check(t.advanceBefore(c-1,read,write,store)==0&&unsigned(t.stage())==s);check(t.advanceBefore(c,read,write,store)==c);}check(writes==1&&controls==1&&refreshes==unsigned(kind==0||gate==0)&&globals==unsigned(kind!=0&&gate==0));++cases;}std::cout<<"PASS: "<<cases<<" pure part modulation properties; all4kinds/all input-gate bytepairs and part handles,255sentinel,wrapped square highbyte, gated child lifetimes, store pairing and budget refusal\n";}
